-- UPS weight-based shipping (Express Saver, 2026 contract rates).
-- Cyprus (00000000-0000-0000-0000-0000000000d1) stays domestic/flat (AKIS pending). All other zones use
-- shipping_rate_tiers keyed by billable weight. Column source: UPS RATES 2026 PDF.

begin;

-- 1. Schema additions -----------------------------------------------------
alter table public.shipping_zones
  add column if not exists zone_code text,
  add column if not exists is_domestic boolean not null default false,
  add column if not exists over_kg_cents integer;

create table if not exists public.shipping_rate_tiers (
  id uuid primary key default gen_random_uuid(),
  zone_id uuid not null references public.shipping_zones(id) on delete cascade,
  max_weight_grams integer not null,
  price_cents integer not null,
  unique (zone_id, max_weight_grams)
);
create index if not exists shipping_rate_tiers_zone_idx on public.shipping_rate_tiers(zone_id);
alter table public.shipping_rate_tiers enable row level security;
drop policy if exists shipping_rate_tiers_public_read on public.shipping_rate_tiers;
create policy shipping_rate_tiers_public_read on public.shipping_rate_tiers for select using (true);
drop policy if exists shipping_rate_tiers_admin_write on public.shipping_rate_tiers;
create policy shipping_rate_tiers_admin_write on public.shipping_rate_tiers
  for all using (public.is_admin()) with check (public.is_admin());

-- 2. Cyprus stays domestic; clear the old made-up EU/Europe/Worldwide zones --
update public.shipping_zones set is_domestic = true, zone_code = 'CY' where id = '00000000-0000-0000-0000-0000000000d1';
-- Detach any order that pointed at an old non-domestic method (defensive:
-- covers a possible orders.shipping_method_id FK; today only Cyprus is used).
update public.orders set shipping_method_id = null where shipping_method_id in (
  select id from public.shipping_methods where zone_id in (
    select id from public.shipping_zones where is_domestic = false
  )
);
-- Remove old non-domestic zones (delete their methods first — no cascade on zone_id).
delete from public.shipping_methods where zone_id in (
  select id from public.shipping_zones where is_domestic = false
);
delete from public.shipping_zones where is_domestic = false;

-- 3. UPS zones ------------------------------------------------------------
  values ('00000000-0000-0000-0000-0000000000e1', 'UPS Zone 1', array['AT','BE','DE','DK','FR','GR','IE','IT','LU','MC','NL','PT','ES','SE']::text[], true, '1', false, 320)
