  values ('00000000-0000-0000-0000-0000000000e6', 'UPS Zone 6', array['AF','AU','CA','CN','HK','ID','IN','JP','KR','MX','MY','PH','PK','PR','SG','TH','TW','US']::text[], true, '6', false, 539)
